// Lưu topic MQTT trước khi thay msg.topic bằng câu SQL
const mqttTopic = String(msg.topic || "").trim();


const match = mqttTopic.match(
    /^sensor\/([A-Za-z0-9_-]{1,50})\/([a-z][a-z0-9_]{0,49})$/
);

if (!match) {
    node.warn(`Topic không hợp lệ: ${mqttTopic}`);
    return [null, null];
}

const deviceCode = match[1];
const property = match[2];

// Payload có thể là:
// {"value": 23.7}
// hoặc chỉ là: 23.7
const data =
    typeof msg.payload === "object" && msg.payload !== null
        ? msg.payload
        : { value: msg.payload };

const value = Number(data.value);

if (!Number.isFinite(value)) {
    node.warn("payload.value không phải là một số hợp lệ");
    return [null, null];
}

// Giới hạn kiểm tra dữ liệu cảm biến
const validRanges = {
    temperature: [-20, 80],
    humidity: [0, 100],
    light_level: [0, 100]
};

const range = validRanges[property];

if (range) {
    const [minValue, maxValue] = range;

    if (value < minValue || value > maxValue) {
        node.warn(
            `Giá trị ${property} nằm ngoài khoảng hợp lệ: ${value}`
        );
        return [null, null];
    }
} else {
    node.warn(
        `Chưa cấu hình khoảng hợp lệ cho ${property}, chỉ kiểm tra kiểu số`
    );
}

// Hàm chuyển chuỗi thành giá trị an toàn khi đưa vào SQL
function sqlString(text) {
    return "'" + String(text).replace(/'/g, "''") + "'";
}

const receivedAt = Date.now();

/*
 * OUTPUT 1: lưu vào MySQL
 *
 * Clone message để việc thay đổi msg.topic thành câu SQL
 * không ảnh hưởng đến message gửi sang Dashboard.
 */
const dbMsg = RED.util.cloneMessage(msg);

// Giữ các thuộc tính cho node update last_seen_at phía sau
dbMsg.device_code = deviceCode;
dbMsg.sensor_property = property;
dbMsg.sensor_value = value;
dbMsg.mqtt_topic = mqttTopic;
dbMsg.received_at = receivedAt;

// Tìm datastream và thêm Observation
dbMsg.topic = `
    INSERT INTO observation (
        datastream_id,
        value,
        observed_at
    )
    SELECT
        d.id,
        ${value},
        NOW()
    FROM datastream d
    INNER JOIN sensor s
        ON s.id = d.sensor_id
    WHERE s.device_code = ${sqlString(deviceCode)}
      AND d.observed_property = ${sqlString(property)}
      AND d.mqtt_topic = ${sqlString(mqttTopic)}
    LIMIT 1
`;

/*
 * OUTPUT 2: gửi dữ liệu thời gian thực sang Dashboard
 *
 * msg.topic được rút gọn thành:
 * temperature hoặc humidity
 * để Switch node trên Dashboard dễ phân loại.
 */
const dashboardValue =
    property === "light_level"
        ? Math.round(value * 10) / 10
        : value;

const dashboardMsg = {
    topic: property,
    payload: dashboardValue,
    device_code: deviceCode,
    mqtt_topic: mqttTopic,
    received_at: receivedAt
};

return [dbMsg, dashboardMsg];

const request =
    typeof msg.payload === "object" &&
    msg.payload !== null &&
    !Array.isArray(msg.payload)
        ? msg.payload
        : {};

// Mã actuator
const deviceCode = String(
    request.device_code || ""
)
    .trim()
    .toUpperCase();

// Giá trị điều khiển yêu cầu
const targetValue = String(
    request.target_value ||
    request.target_state ||
    request.state ||
    ""
)
    .trim()
    .toUpperCase();

// Capability mặc định của hệ thống hiện tại
const capabilityCode = String(
    request.capability_code || "ON_OFF"
)
    .trim()
    .toUpperCase();

// Nguồn tạo task
const rawSource = String(
    request.source || "DASHBOARD"
)
    .trim()
    .toUpperCase();

// Kiểm tra device_code
if (!/^[A-Z0-9_-]{1,50}$/.test(deviceCode)) {
    node.warn(
        `device_code không hợp lệ: ${deviceCode}`
    );
    return null;
}

// Kiểm tra capability_code
if (!/^[A-Z0-9_-]{1,50}$/.test(capabilityCode)) {
    node.warn(
        `capability_code không hợp lệ: ${capabilityCode}`
    );
    return null;
}

// Kiểm tra giá trị yêu cầu
if (!targetValue) {
    node.warn("Thiếu target_value");
    return null;
}

// Vì capability hiện tại là ON_OFF,
// chỉ chấp nhận ON hoặc OFF
if (
    capabilityCode === "ON_OFF" &&
    !["ON", "OFF"].includes(targetValue)
) {
    node.warn(
        `Giá trị ${targetValue} không hợp lệ cho capability ON_OFF`
    );
    return null;
}

// Chuẩn hóa source theo ENUM:
// USER, SYSTEM, AUTO_LOCAL
let commandSource;

switch (rawSource) {
    case "USER":
    case "DASHBOARD":
        commandSource = "USER";
        break;

    case "AUTO":
    case "AUTO_LOCAL":
        commandSource = "AUTO_LOCAL";
        break;

    case "SYSTEM":
    case "TEST":
        commandSource = "SYSTEM";
        break;

    default:
        node.warn(
            `source không hợp lệ: ${rawSource}`
        );
        return null;
}

// Lưu dữ liệu cho các node phía sau
msg.device_code = deviceCode;
msg.capability_code = capabilityCode;
msg.target_value = targetValue;

// Có thể giữ target_state để tương thích
// với các node cũ trong lúc refactor
msg.target_state = targetValue;

msg.command_source = commandSource;
msg.requested_at = Date.now();

// Tìm actuator cùng TaskingCapability
msg.topic = `
    SELECT
        tc.id AS tasking_capability_id,
        tc.capability_code,
        tc.allowed_values,
        tc.command_topic,
        tc.status_topic,

        a.id AS actuator_id,
        a.device_code,
        a.name AS actuator_name,
        a.type AS actuator_type

    FROM tasking_capability AS tc

    INNER JOIN actuator AS a
        ON a.id = tc.actuator_id

    WHERE a.device_code = ?
      AND tc.capability_code = ?

    LIMIT 1
`;

msg.payload = [
    deviceCode,
    capabilityCode
];

return msg;

const rows = msg.payload;

// Kiểm tra kết quả truy vấn
if (!Array.isArray(rows) || rows.length === 0) {
    node.error(
        `Không tìm thấy capability ${msg.capability_code} ` +
        `cho thiết bị ${msg.device_code}`,
        msg
    );
    return null;
}

const capability = rows[0];

// Kiểm tra ID capability
const capabilityId = Number(
    capability.tasking_capability_id
);

if (
    !Number.isInteger(capabilityId) ||
    capabilityId <= 0
) {
    node.error(
        "tasking_capability_id không hợp lệ",
        msg
    );
    return null;
}

// Đọc allowed_values
let allowedValues = capability.allowed_values;

if (typeof allowedValues === "string") {
    try {
        allowedValues = JSON.parse(allowedValues);
    } catch (error) {
        node.error(
            "allowed_values không phải JSON hợp lệ",
            msg
        );
        return null;
    }
}

if (!Array.isArray(allowedValues)) {
    node.error(
        "allowed_values phải là một mảng",
        msg
    );
    return null;
}

// Chuẩn hóa các giá trị được phép
allowedValues = allowedValues.map(value =>
    String(value).trim().toUpperCase()
);

// Kiểm tra target_value theo dữ liệu trong capability
if (!allowedValues.includes(msg.target_value)) {
    node.error(
        `Giá trị ${msg.target_value} không hợp lệ. ` +
        `Các giá trị cho phép: ${allowedValues.join(", ")}`,
        msg
    );
    return null;
}

// Lưu thông tin cho các node phía sau
msg.tasking_capability_id = capabilityId;
msg.actuator_id = Number(capability.actuator_id);

msg.actuator_name = capability.actuator_name;
msg.actuator_type = capability.actuator_type;

msg.command_topic = capability.command_topic;
msg.status_topic = capability.status_topic;
msg.allowed_values = allowedValues;

// Chuẩn bị INSERT task
msg.topic = `
    INSERT INTO task (
        tasking_capability_id,
        target_value,
        source,
        status,
        created_at
    )
    VALUES (?, ?, ?, 'PENDING', NOW())
`;

msg.payload = [
    msg.tasking_capability_id,
    msg.target_value,
    msg.command_source
];

return msg;

const result = msg.payload;

if (!result || Number(result.affectedRows) !== 1) {
    node.error(`Không tạo được task cho thiết bị ${msg.device_code}`, msg);
    return null;
}

const taskId = Number(result.insertId);
if (!Number.isInteger(taskId) || taskId <= 0) {
    node.error(`task_id không hợp lệ: ${result.insertId}`, msg);
    return null;
}

const commandTopic = String(msg.command_topic || "").trim();
if (!commandTopic) {
    node.error(`Không tìm thấy command_topic của ${msg.device_code}`, msg);
    return null;
}

const deviceCode = String(msg.device_code || "").trim().toUpperCase();
const capabilityCode = String(msg.capability_code || "").trim().toUpperCase();
const targetValue = String(msg.target_value || "").trim().toUpperCase();
const source = String(msg.command_source || "USER").trim().toUpperCase();

if (!deviceCode || !capabilityCode || !targetValue) {
    node.error("Thiếu dữ liệu bắt buộc để tạo MQTT command", msg);
    return null;
}

function toVietnamIso(timestamp) {
    const date = new Date(timestamp || Date.now());
    if (Number.isNaN(date.getTime())) {
        return null;
    }
    return new Date(date.getTime() + 7 * 60 * 60 * 1000)
        .toISOString()
        .replace("Z", "+07:00");
}

msg.task_id = taskId;
msg.topic = commandTopic;
msg.payload = JSON.stringify({
    task_id: taskId,
    device_code: deviceCode,
    capability_code: capabilityCode,
    target_value: targetValue,
    source: source,
    requested_at: toVietnamIso(msg.requested_at)
});
msg.qos = 1;
msg.retain = false;

return msg;

const data = msg.payload;

function reject(reason) {
    const errorMsg = RED.util.cloneMessage(msg);
    errorMsg.error_reason = reason;
    node.warn(reason);
    return [null, null, errorMsg];
}

if (!data || typeof data !== "object" || Array.isArray(data)) {
    return reject("Payload phải là JSON object");
}

const requiredFields = [
    "task_id",
    "device_code",
    "capability_code",
    "current_value",
    "status",
    "reported_at"
];

for (const field of requiredFields) {
    if (data[field] === undefined || data[field] === null || String(data[field]).trim() === "") {
        return reject(`Thiếu trường: ${field}`);
    }
}

const taskId = Number(data.task_id);
const deviceCode = String(data.device_code).trim().toUpperCase();
const capabilityCode = String(data.capability_code).trim().toUpperCase();
const currentValue = String(data.current_value).trim().toUpperCase();
const taskStatus = String(data.status).trim().toUpperCase();
const reportedAt = String(data.reported_at).trim();

if (!Number.isInteger(taskId) || taskId <= 0) {
    return reject("task_id không hợp lệ");
}
if (!/^[A-Z0-9_-]{1,50}$/.test(deviceCode)) {
    return reject("device_code không hợp lệ");
}
if (!/^[A-Z0-9_-]{1,50}$/.test(capabilityCode)) {
    return reject("capability_code không hợp lệ");
}
if (capabilityCode === "ON_OFF" && !["ON", "OFF"].includes(currentValue)) {
    return reject("current_value chỉ được nhận ON hoặc OFF với capability ON_OFF");
}
if (!["COMPLETED", "FAILED"].includes(taskStatus)) {
    return reject("status chỉ được nhận COMPLETED hoặc FAILED");
}
if (Number.isNaN(Date.parse(reportedAt))) {
    return reject("reported_at không đúng định dạng ISO 8601");
}

const mqttTopic = String(msg.topic || "").trim();
const match = mqttTopic.match(/^actuator\/([A-Z0-9_-]{1,50})\/status$/);
if (!match) {
    return reject(`Topic không hợp lệ: ${mqttTopic}`);
}
if (match[1] !== deviceCode) {
    return reject(`device_code trong topic (${match[1]}) không khớp payload (${deviceCode})`);
}

const statusData = {
    task_id: taskId,
    device_code: deviceCode,
    capability_code: capabilityCode,
    current_value: currentValue,
    status: taskStatus,
    reported_at: reportedAt,
    error_code: data.error_code || null,
    message: data.message || null,
    mqtt_topic: mqttTopic
};

const dbMsg = RED.util.cloneMessage(msg);
dbMsg.actuator_status = statusData;
dbMsg.topic = `
    UPDATE task AS t
    INNER JOIN tasking_capability AS tc
        ON tc.id = t.tasking_capability_id
    INNER JOIN actuator AS a
        ON a.id = tc.actuator_id
    SET
        t.status = ?,
        t.completed_at = NOW()
    WHERE t.id = ?
      AND a.device_code = ?
      AND tc.capability_code = ?
      AND tc.status_topic = ?
      AND t.status = 'PENDING'
      AND (
          ? = 'FAILED'
          OR UPPER(t.target_value) = ?
      )
`;
dbMsg.payload = [
    taskStatus,
    taskId,
    deviceCode,
    capabilityCode,
    mqttTopic,
    taskStatus,
    currentValue
];

const dashboardMsg = {
    topic: "actuator_status",
    device_code: deviceCode,
    capability_code: capabilityCode,
    current_value: currentValue,
    task_status: taskStatus,
    task_id: taskId,
    reported_at: reportedAt,
    error_code: data.error_code || null,
    message: data.message || null
};

return [dbMsg, dashboardMsg, null];

const result = msg.payload;
const status = msg.actuator_status;
const affectedRows = result && result.affectedRows !== undefined
    ? Number(result.affectedRows)
    : 0;

if (affectedRows === 1) {
    msg.payload = {
        success: true,
        task_id: status.task_id,
        device_code: status.device_code,
        current_value: status.current_value,
        status: status.status
    };
    return [msg, null];
}

msg.payload = {
    success: false,
    message: "Không cập nhật được task",
    possible_reasons: [
        "task_id không tồn tại",
        "task đã COMPLETED hoặc FAILED",
        "device_code không đúng",
        "capability_code không đúng",
        "status_topic không đúng",
        "current_value khác target_value"
    ],
    actuator_status: status
};
return [null, msg];

const command = msg.payload || {};

const deviceCode = String(
    command.device_code || ""
).trim();

const targetState = String(
    command.target_state || ""
).toUpperCase();

const validDevices = [
    "MIST_PUMP_01",
    "VENT_FAN_01",
    "GROW_LIGHT_01"
];

if (!validDevices.includes(deviceCode)) {
    node.error("device_code không hợp lệ", msg);
    return null;
}

if (!["ON", "OFF"].includes(targetState)) {
    node.error("target_state phải là ON hoặc OFF", msg);
    return null;
}

msg.payload = {
    device_code: deviceCode,
    capability_code: "ON_OFF",
    target_state: targetState,
    source: command.source || "USER"
};

return msg;

const data = msg.payload || {};

const deviceCode = String(data.device_code || "").trim();

const currentValue = String(
    data.current_value ||
    data.state ||
    "OFF"
).toUpperCase();

const taskStatus = String(
    data.status ||
    "COMPLETED"
).toUpperCase();

const reportedAt =
    data.reported_at ||
    new Date().toLocaleString("vi-VN");

const cardMessage = {
    payload: {
        task_id: data.task_id,
        device_code: deviceCode,
        capability_code: data.capability_code || "ON_OFF",
        current_value: currentValue,
        status: taskStatus,
        reported_at: reportedAt
    }
};

const latestMessage = {
    payload:
        `${deviceCode} | ` +
        `${currentValue} | ` +
        `${taskStatus} | ` +
        `${reportedAt}`
};

let pumpOutput = null;
let fanOutput = null;
let lightOutput = null;

switch (deviceCode) {
    case "MIST_PUMP_01":
        pumpOutput = cardMessage;
        break;

    case "VENT_FAN_01":
        fanOutput = cardMessage;
        break;

    case "GROW_LIGHT_01":
        lightOutput = cardMessage;
        break;

    default:
        node.warn({
            message: "Không xác định được actuator",
            device_code: deviceCode,
            payload: data
        });

        return null;
}

return [
    pumpOutput,
    fanOutput,
    lightOutput,
    latestMessage
];

if (!Array.isArray(msg.payload)) {
    node.warn("Dữ liệu gửi vào table không phải mảng");
    return null;
}

msg.payload = msg.payload.map(row => ({
    task_id: row.task_id,
    thiet_bi: row.thiet_bi,
    device_code: row.device_code,
    lenh: row.lenh,
    nguon: row.nguon,
    trang_thai: row.trang_thai,
    tao_luc: row.tao_luc,
    hoan_thanh_luc: row.hoan_thanh_luc || ""
}));

msg.class = "recent-task-table";

return msg;

