const periods = {
    "24h": { hours: 24, bucketSeconds: 10 * 60, label: "24 giờ gần nhất" },
    "7d":  { hours: 7 * 24, bucketSeconds: 60 * 60, label: "7 ngày gần nhất" },
    "30d": { hours: 30 * 24, bucketSeconds: 6 * 60 * 60, label: "30 ngày gần nhất" },
    "90d": { hours: 90 * 24, bucketSeconds: 24 * 60 * 60, label: "90 ngày gần nhất" }
};

let periodKey = String(msg.payload || "");
if (periods[periodKey]) {
    flow.set("history_period", periodKey);
} else {
    periodKey = flow.get("history_period") || "24h";
}

const period = periods[periodKey] || periods["24h"];
const common = {
    period_key: periodKey,
    period_label: period.label,
    query_started_at: Date.now()
};

const sensorStats = {
    ...common,
    topic: `
        SELECT
            ROUND(AVG(CASE WHEN property_name = 'temperature' THEN avg_value END), 2) AS avg_temperature,
            ROUND(AVG(CASE WHEN property_name = 'humidity' THEN avg_value END), 2) AS avg_humidity,
            COALESCE(SUM(CASE WHEN property_name = 'temperature' THEN sample_count ELSE 0 END), 0) AS temperature_samples,
            COALESCE(SUM(CASE WHEN property_name = 'humidity' THEN sample_count ELSE 0 END), 0) AS humidity_samples,
            COUNT(DISTINCT CASE WHEN property_name = 'temperature' THEN device_code END) AS temperature_sensors,
            COUNT(DISTINCT CASE WHEN property_name = 'humidity' THEN device_code END) AS humidity_sensors
        FROM (
            SELECT
                s.device_code,
                LOWER(d.observed_property) AS property_name,
                AVG(o.value) AS avg_value,
                COUNT(*) AS sample_count
            FROM observation AS o
            INNER JOIN datastream AS d ON d.id = o.datastream_id
            INNER JOIN sensor AS s ON s.id = d.sensor_id
            WHERE o.observed_at >= DATE_SUB(NOW(), INTERVAL ? HOUR)
              AND LOWER(d.observed_property) IN ('temperature', 'humidity')
            GROUP BY s.device_code, LOWER(d.observed_property)
        ) AS sensor_period_stats
    `,
    payload: [period.hours]
};

const taskStats = {
    ...common,
    topic: `
        SELECT
            COALESCE(SUM(CASE WHEN t.status = 'COMPLETED' THEN 1 ELSE 0 END), 0) AS completed_tasks,
            COUNT(*) AS total_tasks
        FROM task AS t
        WHERE t.created_at >= DATE_SUB(NOW(), INTERVAL ? HOUR)
    `,
    payload: [period.hours]
};

const temperatureHistory = {
    ...common,
    topic: `
        SELECT
            s.device_code,
            CAST(UNIX_TIMESTAMP(MIN(o.observed_at)) * 1000 AS UNSIGNED) AS time,
            ROUND(AVG(o.value), 2) AS value
        FROM observation AS o
        INNER JOIN datastream AS d ON d.id = o.datastream_id
        INNER JOIN sensor AS s ON s.id = d.sensor_id
        WHERE LOWER(d.observed_property) = 'temperature'
          AND o.observed_at >= DATE_SUB(NOW(), INTERVAL ? HOUR)
        GROUP BY
            s.device_code,
            FLOOR(UNIX_TIMESTAMP(o.observed_at) / ?)
        ORDER BY time ASC, s.device_code ASC
    `,
    payload: [period.hours, period.bucketSeconds]
};

const humidityHistory = {
    ...common,
    topic: `
        SELECT
            s.device_code,
            CAST(UNIX_TIMESTAMP(MIN(o.observed_at)) * 1000 AS UNSIGNED) AS time,
            ROUND(AVG(o.value), 2) AS value
        FROM observation AS o
        INNER JOIN datastream AS d ON d.id = o.datastream_id
        INNER JOIN sensor AS s ON s.id = d.sensor_id
        WHERE LOWER(d.observed_property) = 'humidity'
          AND o.observed_at >= DATE_SUB(NOW(), INTERVAL ? HOUR)
        GROUP BY
            s.device_code,
            FLOOR(UNIX_TIMESTAMP(o.observed_at) / ?)
        ORDER BY time ASC, s.device_code ASC
    `,
    payload: [period.hours, period.bucketSeconds]
};

return [sensorStats, taskStats, temperatureHistory, humidityHistory];

const row = Array.isArray(msg.payload) && msg.payload.length ? msg.payload[0] : {};

function metric(value, suffix) {
    if (value === null || value === undefined || value === "") return "—";
    const number = Number(value);
    return Number.isFinite(number) ? `${number.toFixed(2)} ${suffix}` : "—";
}

const temperature = { ...msg, payload: metric(row.avg_temperature, "°C") };
const humidity = { ...msg, payload: metric(row.avg_humidity, "%") };

const tempSamples = Number(row.temperature_samples || 0);
const humSamples = Number(row.humidity_samples || 0);
const tempSensors = Number(row.temperature_sensors || 0);
const humSensors = Number(row.humidity_sensors || 0);
const updatedAt = new Date().toLocaleString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    hour12: false
});

const status = {
    ...msg,
    payload: `Đã tải ${msg.period_label || "dữ liệu lịch sử"} • ${tempSensors}/${humSensors} sensor nhiệt độ/độ ẩm • ${tempSamples + humSamples} mẫu • ${updatedAt}`
};

return [temperature, humidity, status];

const row = Array.isArray(msg.payload) && msg.payload.length ? msg.payload[0] : {};
const completed = Number(row.completed_tasks || 0);
const total = Number(row.total_tasks || 0);
return [
    { ...msg, payload: completed },
    { ...msg, payload: total }
];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = rows
    .map(row => ({
        device_code: String(row.device_code || "UNKNOWN_SENSOR"),
        time: Number(row.time),
        value: Number(row.value)
    }))
    .filter(row => Number.isFinite(row.time) && Number.isFinite(row.value));
msg.action = "replace";
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = rows
    .map(row => ({
        device_code: String(row.device_code || "UNKNOWN_SENSOR"),
        time: Number(row.time),
        value: Number(row.value)
    }))
    .filter(row => Number.isFinite(row.time) && Number.isFinite(row.value));
msg.action = "replace";
return msg;

const source = msg.error && msg.error.source ? msg.error.source.name : "MySQL";
const message = msg.error && msg.error.message ? msg.error.message : "Không xác định";
msg.payload = `Lỗi tải lịch sử tại ${source}: ${message}`;
return msg;

let state = flow.get("device_overview_status") || {
    mode: "MANUAL",

    fan: {
        value: "OFF",
        failed: false
    },

    light: {
        value: "OFF",
        failed: false
    },

    pump: {
        value: "OFF",
        failed: false
    },

    esp32: "OFFLINE",

    updated_at: null
};

/*
 * Cập nhật chế độ vận hành.
 *
 * Dữ liệu đầu vào:
 * msg.status_type = "mode"
 * msg.payload = "MANUAL" hoặc "AUTO"
 */
if (msg.status_type === "mode") {
    const mode = String(msg.payload || "")
        .trim()
        .toUpperCase();

    if (!["MANUAL", "AUTO"].includes(mode)) {
        return null;
    }

    state.mode = mode;
}

/*
 * Cập nhật trạng thái ESP32.
 *
 * Dữ liệu đầu vào:
 * msg.status_type = "esp32"
 * msg.payload = "ONLINE" hoặc "OFFLINE"
 */
else if (msg.status_type === "esp32") {
    const esp32Status = String(msg.payload || "")
        .trim()
        .toUpperCase();

    if (!["ONLINE", "OFFLINE"].includes(esp32Status)) {
        return null;
    }

    state.esp32 = esp32Status;
}

/*
 * Cập nhật trạng thái actuator.
 *
 * Payload ví dụ:
 * {
 *   "device_code": "VENT_FAN_01",
 *   "current_value": "ON",
 *   "status": "COMPLETED"
 * }
 */
else {
    const data = msg.payload;

    if (!data || typeof data !== "object") {
        return null;
    }

    const deviceCode = String(data.device_code || "")
        .trim()
        .toUpperCase();

    const currentValue = String(data.current_value || "")
        .trim()
        .toUpperCase();

    const taskStatus = String(
        data.status || data.task_status || ""
    )
        .trim()
        .toUpperCase();

    if (!["ON", "OFF"].includes(currentValue)) {
        return null;
    }

    const deviceMap = {
        MIST_PUMP_01: "pump",
        VENT_FAN_01: "fan",
        GROW_LIGHT_01: "light"
    };

    const deviceKey = deviceMap[deviceCode];

    if (!deviceKey) {
        return null;
    }

    state[deviceKey] = {
        value: currentValue,
        failed: taskStatus === "FAILED"
    };

    /*
     * Có dữ liệu trạng thái actuator từ ESP32
     * thì tạm xem ESP32 đang online.
     */
    state.esp32 = "ONLINE";
}

state.updated_at = new Date().toLocaleString("vi-VN");

flow.set("device_overview_status", state);

msg.payload = state;

delete msg.status_type;
delete msg.device_code;

return msg;

if (!Array.isArray(msg.payload)) {
    node.error("Kết quả truy vấn không phải mảng", msg);
    return null;
}

msg.payload = msg.payload
    .map(row => ({
        time: Number(row.time),
        value: Number(row.temperature)
    }))
    .filter(point =>
        Number.isFinite(point.time) &&
        Number.isFinite(point.value)
    );

msg.topic = "Nhiệt độ";
msg.action = "replace";

return msg;

if (!Array.isArray(msg.payload)) {
    node.error("Kết quả truy vấn độ ẩm không phải mảng", msg);
    return null;
}

const points = msg.payload
    .map(row => ({
        time: Number(row.time),
        value: Number(row.humidity)
    }))
    .filter(point =>
        Number.isFinite(point.time) &&
        Number.isFinite(point.value)
    )
    .sort((a, b) => a.time - b.time);

msg.topic = "Độ ẩm";
msg.action = "replace";
msg.payload = points;

node.status({
    fill: points.length > 0 ? "green" : "yellow",
    shape: "dot",
    text: `${points.length} điểm`
});

return msg;

const property = String(msg.topic || "")
    .trim()
    .toLowerCase();

const thresholds = {
    temperature: {
        min: 25,
        max: 32,
        unit: "°C"
    },
    humidity: {
        min: 80,
        max: 90,
        unit: "%"
    },
    light_level: {
        min: 20,
        max: 30,
        unit: "%"
    }
};

if (!thresholds[property]) {
    return null;
}

const rawValue =
    msg.payload &&
    typeof msg.payload === "object" &&
    msg.payload.value !== undefined
        ? msg.payload.value
        : msg.payload;

const value = Number(rawValue);

if (!Number.isFinite(value)) {
    node.warn(`Không thể đánh giá ${property}: giá trị không hợp lệ`);
    return null;
}

let state = flow.get("environment_overview_status") || {
    temperature: {
        value: null,
        status: "NO_DATA",
        label: "Chưa có dữ liệu",
        min: 25,
        max: 32,
        unit: "°C"
    },
    humidity: {
        value: null,
        status: "NO_DATA",
        label: "Chưa có dữ liệu",
        min: 80,
        max: 90,
        unit: "%"
    },
    light_level: {
        value: null,
        status: "NO_DATA",
        label: "Chưa có dữ liệu",
        min: 20,
        max: 30,
        unit: "%"
    },
    updated_at: null
};

const rule = thresholds[property];
const isNormal = value >= rule.min && value <= rule.max;

state[property] = {
    value: Math.round(value * 10) / 10,
    status: isNormal ? "NORMAL" : "ABNORMAL",
    label: isNormal ? "Bình thường" : "Bất thường",
    min: rule.min,
    max: rule.max,
    unit: rule.unit
};

state.updated_at = new Date().toLocaleString("vi-VN");

flow.set("environment_overview_status", state);

msg.payload = state;
msg.topic = "environment_status";

return msg;
